package com.example.signup;

import java.util.concurrent.ThreadPoolExecutor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@Configuration
public class AsyncConfig {
    @Bean
    public ThreadPoolTaskExecutor mailExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(4);
        executor.setMaxPoolSize(8);
        executor.setQueueCapacity(500);
        executor.setThreadNamePrefix("mail-");
        executor.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());
        executor.setWaitForTasksToCompleteOnShutdown(true);
        executor.setAwaitTerminationSeconds(30);
        return executor;
    }
}

public User signup(SignupRequest request) {
    User user = userRepository.save(User.from(request));
    try {
        welcomeMailer.send(user);
    } catch (MailException e) {
        failedMailRepository.save(new FailedMail(user.getId(), e.getMessage()));
    }
    return user;
}

@Async("mailExecutor")
public CompletableFuture<Void> send(User user) {
    mailGateway.send(user.getEmail(), "welcome");
    return CompletableFuture.completedFuture(null);
}

public User signup(SignupRequest request) {
    User user = userRepository.save(User.from(request));
    welcomeMailer.send(user).exceptionally(ex -> {
        failedMailRepository.save(new FailedMail(user.getId(), ex.getMessage()));
        return null;
    });
    return user;
}
